import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aStr = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aStr[i]);
        }

        int mid = n / 2;
        List<Integer> firstHalf = new ArrayList<>();
        List<Integer> secondHalf = new ArrayList<>();

        computeSums1(0, 0, a, m, mid, firstHalf);
        computeSums2(mid, 0, a, m, n, secondHalf);

        Collections.sort(firstHalf);

        int result = 0;
        for (int val : secondHalf) {
            int target = m - val;
            int index = Collections.binarySearch(firstHalf, target);
            if (index < 0) {
                index = -index - 1;
            }
            if (index > 0) {
                int sumCandidate = firstHalf.get(index - 1) + val;
                if (sumCandidate > result) {
                    result = sumCandidate;
                }
            }
        }
        System.out.println(result);
    }

    private static void computeSums1(int i, int total, int[] a, int m, int mid, List<Integer> firstHalf) {
        if (i == mid) {
            firstHalf.add(total);
        } else {
            computeSums1(i + 1, (total + a[i]) % m, a, m, mid, firstHalf);
            computeSums1(i + 1, total, a, m, mid, firstHalf);
        }
    }

    private static void computeSums2(int i, int total, int[] a, int m, int n, List<Integer> secondHalf) {
        if (i == n) {
            secondHalf.add(total);
        } else {
            computeSums2(i + 1, (total + a[i]) % m, a, m, n, secondHalf);
            computeSums2(i + 1, total, a, m, n, secondHalf);
        }
    }
}
